    bytes public initCalldata;
    bool public lastReentrantSucceeded;

    constructor(address _target) {
        target = _target;
    }

    function setupInitializeCalldata(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
